sections.body:
The previous concept introduced the mechanism; here is the contract. Every Writable stream has an internal buffer and a configured **highWaterMark**, a threshold (in bytes by default) for how much unflushed data counts as 'a lot.' Calling writable.write(chunk) always accepts and queues the chunk, whatever the buffer level, but its **return value** tells you whether to keep going (true) or pause and wait (false, meaning the buffer is now at or above highWaterMark):

```javascript
function writeRespectingBackpressure(writable, chunks) {
  let i = 0;
  function writeNext() {
    let ok = true;
    while (i < chunks.length && ok) {
      ok = writable.write(chunks[i]);   // returns false once the buffer is full
      i++;
    }
    if (i < chunks.length) {
      // buffer is full: stop writing, wait for 'drain' before resuming
      writable.once('drain', writeNext);
    }
  }
  writeNext();
}
```

Once write() returns false, the correct response is to stop calling write() on that stream and wait for a 'drain' event, which fires once the internal buffer has been flushed enough to accept more. Continuing to call .write() after a false return doesn't raise an error or reject anything; Node keeps accepting data into the buffer. That's the trap: nothing forces you to respect the signal, so ignoring it is harmless at first and expensive later.

Beyond the error handling covered in the previous concept, .pipe() and stream.pipeline() are recommended defaults because they implement the write()-return-value-and-drain dance shown above correctly every time. When you write source.pipe(destination), .pipe() attaches a 'data' listener on source that calls destination.write(chunk); when that write() returns false, .pipe() calls source.pause() to stop further 'data' events, and when destination emits 'drain', it calls source.resume(). That's the whole backpressure story, handled for you as long as you use .pipe()/pipeline() instead of hand-rolling 'data' handlers with direct .write() calls.

The risk is in code that bypasses pipe(): listening to 'data' events and calling .write() on a destination inside the handler, without checking the return value or listening for 'drain':

```javascript
// DANGEROUS: never checks write()'s return value, never waits for 'drain'
// fragment: assumes `readable` and `writable` streams already exist
readable.on('data', (chunk) => {
  writable.write(chunk);   // if writable can't keep up, this buffers unboundedly
});
```

This looks fine in a quick manual test, because a small file or a fast destination never triggers a false return. The bug stays invisible until the data size or the destination's speed crosses the threshold where backpressure would kick in, which in production usually means the first time it matters.

examples.code:
const fs = require('fs');

function copyManually(sourcePath, destPath, onDone) {
  const source = fs.createReadStream(sourcePath);
  const dest = fs.createWriteStream(destPath);

  source.on('data', (chunk) => {
    const canContinue = dest.write(chunk);
    if (!canContinue) {
      source.pause();   // stop reading until dest catches up
    }
  });

  dest.on('drain', () => {
    source.resume();    // dest is ready for more, so resume reading
  });

  source.on('end', () => dest.end());
  dest.on('finish', onDone);
  source.on('error', (err) => dest.destroy(err));
  dest.on('error', (err) => { source.destroy(); onDone(err); });
}

const fs = require('fs');

// DANGEROUS: no return-value check, no pause/resume, no drain listener at all
function copyDangerously(sourcePath, destPath, onDone) {
  const source = fs.createReadStream(sourcePath);
  const dest = fs.createWriteStream(destPath);

  source.on('data', (chunk) => {
    dest.write(chunk);   // return value silently discarded
  });

  source.on('end', () => dest.end());
  dest.on('finish', onDone);
}

// Works in local testing with a small file and a fast local disk...
copyDangerously('./small-test-file.txt', './copy.txt', () => console.log('done'));
// ...but with a huge file and a slow destination (e.g. a network mount, a rate-limited
// upload), dest's internal buffer grows without bound because nothing ever tells
// `source` to pause, and memory climbs until the data is flushed.

const fs = require('fs');

// Equivalent backpressure behavior to the manual, correct version above,
// but pipe() implements the write()/pause/drain/resume dance for you
function copyWithPipe(sourcePath, destPath, onDone) {
  const source = fs.createReadStream(sourcePath);
  source.on('error', onDone);   // pipe() does not forward source errors
  source.pipe(fs.createWriteStream(destPath))
    .on('finish', onDone)
    .on('error', onDone);
}

copyWithPipe('./huge-file.bin', './copy-of-huge-file.bin', (err) => {
  if (err) return console.error('Copy failed:', err.message);
  console.log('Copy finished, memory usage stayed bounded throughout.');
});

